// after: 'extracted for reuse'
+function useString(initial = "") {
+  const [value, setValue] = useState(initial);
+  return { value, setValue };
+}
+function useBoolean(initial = false) {
+  const [value, setValue] = useState(initial);
+  return { value, on: () => setValue(true), off: () => setValue(false) };
+}
+function SearchBox() {
+  const query = useString();
+  const open = useBoolean();
+  return (
+    <div>
+      <input value={query.value} onChange={(e) => query.setValue(e.target.value)} onFocus={open.on} />
+      {open.value && <Results query={query.value} />}
+    </div>
+  );
+}
+// both hooks are used in exactly this one component
